1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"sort"
10		"strings"
11		"syscall"
12	)
13	
14	// Manual review and false-positive analysis work strictly on top of
15	// archived evidence: submitting a review, querying revision history and
16	// re-evaluating a height range never need the original input files, never
17	// contact any network, never re-write a report, the enabled version or an
18	// alert record, and never trigger or revoke alerts.
19	
20	// Review statuses. A human marks an archived conclusion either as a real
21	// risk or as a false positive; submitting "unreviewed" withdraws earlier
22	// judgments of the same object without deleting the history.
23	const (
24		ReviewStatusReal          = "real"
25		ReviewStatusFalsePositive = "false_positive"
26		ReviewStatusUnreviewed    = "unreviewed"
27	)
28	
29	// Evaluation buckets for original conclusions carrying a valid review:
30	// real risks split into retained vs missed, false positives into still hit
31	// vs eliminated. Candidate hits without a valid review are pending.
32	const (
33		BucketRetained   = "retained"
34		BucketMissed     = "missed"
35		BucketStillHit   = "stillHit"
36		BucketEliminated = "eliminated"
37		BucketPending    = "pending"
38	)
39	
40	// ErrUnknownConclusion reports a review action targeting a conclusion that
41	// no archived report carries.
42	var ErrUnknownConclusion = errors.New("unknown conclusion")
43	
44	// ErrReviewConflict reports a submission whose expectedVersion is behind the
45	// object's current version.
46	var ErrReviewConflict = errors.New("review version conflict")
47	
48	// ErrSubmissionConflict reports a submission ID already stored with
49	// different field values. Submission IDs are unique archive-wide.
50	var ErrSubmissionConflict = errors.New("submission id already used with different content")
51	
52	// conclusionKey is the reviewed object's identity: chain, block hash,
53	// victim tx hash and conclusion kind. It deliberately excludes the alert
54	// channel, and blocks at the same height with different hashes are
55	// different objects.
56	type conclusionKey struct {
57		chainID   string
58		blockHash string
59		txHash    string
60		kind      string
61	}
62	
63	// ReviewRevision is one immutable submission. Revisions are append-only:
64	// rejudgments and withdrawals add a new revision while every earlier one is
65	// retained. ExpectedVersion records the optimistic-concurrency base the
66	// submitter believed in (0 for the first submission), keeping each
67	// revision's full submission content auditable.
68	type ReviewRevision struct {
69		Version         int    `json:"version"`
70		SubmissionID    string `json:"submissionId"`
71		Operator        string `json:"operator"`
72		Reason          string `json:"reason"`
73		Status          string `json:"status"`
74		ExpectedVersion int    `json:"expectedVersion"`
75	}
76	
77	// ReviewObject is the append-only revision stream for one conclusion
78	// identity. The current version is len(Revisions); the current status is
79	// the last revision's status (an "unreviewed" tail means withdrawn).
80	type ReviewObject struct {
81		ChainID   string           `json:"chainId"`
82		BlockHash string           `json:"blockHash"`
83		TxHash    string           `json:"txHash"`
84		Kind      string           `json:"kind"`
85		Revisions []ReviewRevision `json:"revisions"`
86	}
87	
88	func (o ReviewObject) key() conclusionKey {
89		return conclusionKey{o.ChainID, o.BlockHash, o.TxHash, o.Kind}
90	}
91	
92	// ReviewSubmission is one submitted review.
93	type ReviewSubmission struct {
94		ChainID         string
95		BlockHash       string
96		TxHash          string
97		Kind            string
98		SubmissionID    string
99		Operator        string
100		Reason          string
101		Status          string
102		ExpectedVersion int
103	}
104	
105	func (s ReviewSubmission) key() conclusionKey {
106		return conclusionKey{s.ChainID, s.BlockHash, s.TxHash, s.Kind}
107	}
108	
109	// contentEqual reports whether two submissions carry identical field
110	// values, including the target identity and the expected version.
111	func (s ReviewSubmission) contentEqual(o ReviewSubmission) bool {
112		return s == o
113	}
114	
115	func (s ReviewSubmission) revision(version int) ReviewRevision {
116		return ReviewRevision{
117			Version:         version,
118			SubmissionID:    s.SubmissionID,
119			Operator:        s.Operator,
120			Reason:          s.Reason,
121			Status:          s.Status,
122			ExpectedVersion: s.ExpectedVersion,
123		}
124	}
125	
126	// reviewSpec mirrors one submission document. Pointers distinguish missing
127	// fields from explicit zero values; the decoder rejects unknown fields.
128	type reviewSpec struct {
129		ChainID         *string `json:"chainId"`
130		BlockHash       *string `json:"blockHash"`
131		TxHash          *string `json:"txHash"`
132		Kind            *string `json:"kind"`
133		SubmissionID    *string `json:"submissionId"`
134		Operator        *string `json:"operator"`
135		Reason          *string `json:"reason"`
136		Status          *string `json:"status"`
137		ExpectedVersion *int    `json:"expectedVersion"`
138	}
139	
140	// ParseReviewSubmission validates one submission document. Identity fields
141	// and operator/reason/submissionId must be non-empty, the status must be
142	// one of real, false_positive or unreviewed, expectedVersion must be a
143	// non-negative integer, and the kind must be a known conclusion kind.
144	func ParseReviewSubmission(raw []byte) (ReviewSubmission, error) {
145		var spec reviewSpec
146		dec := json.NewDecoder(bytes.NewReader(raw))
147		dec.DisallowUnknownFields()
148		if err := dec.Decode(&spec); err != nil {
149			return ReviewSubmission{}, fmt.Errorf("invalid review spec: %w", err)
150		}
151		if dec.More() {
152			return ReviewSubmission{}, errors.New("invalid review spec: unexpected trailing data")
153		}
154		chainID, err := nonEmpty("chainId", spec.ChainID)
155		if err != nil {
156			return ReviewSubmission{}, err
157		}
158		blockHash, err := nonEmpty("blockHash", spec.BlockHash)
159		if err != nil {
160			return ReviewSubmission{}, err
161		}
162		txHash, err := nonEmpty("txHash", spec.TxHash)
163		if err != nil {
164			return ReviewSubmission{}, err
165		}
166		kind, err := nonEmpty("kind", spec.Kind)
167		if err != nil {
168			return ReviewSubmission{}, err
169		}
170		if kind != SuppressSandwich && kind != SuppressDisplacement {
171			return ReviewSubmission{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
172		}
173		submissionID, err := nonEmpty("submissionId", spec.SubmissionID)
174		if err != nil {
175			return ReviewSubmission{}, err
176		}
177		operator, err := nonEmpty("operator", spec.Operator)
178		if err != nil {
179			return ReviewSubmission{}, err
180		}
181		reason, err := nonEmpty("reason", spec.Reason)
182		if err != nil {
183			return ReviewSubmission{}, err
184		}
185		status, err := nonEmpty("status", spec.Status)
186		if err != nil {
187			return ReviewSubmission{}, err
188		}
189		switch status {
190		case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
191		default:
192			return ReviewSubmission{}, fmt.Errorf("invalid status %q (want %s, %s or %s)",
193				status, ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed)
194		}
195		if spec.ExpectedVersion == nil {
196			return ReviewSubmission{}, errors.New("expectedVersion is required (non-negative integer)")
197		}
198		if *spec.ExpectedVersion < 0 {
199			return ReviewSubmission{}, fmt.Errorf("expectedVersion must be non-negative, got %d", *spec.ExpectedVersion)
200		}
201		return ReviewSubmission{
202			ChainID:         chainID,
203			BlockHash:       blockHash,
204			TxHash:          txHash,
205			Kind:            kind,
206			SubmissionID:    submissionID,
207			Operator:        operator,
208			Reason:          reason,
209			Status:          status,
210			ExpectedVersion: *spec.ExpectedVersion,
211		}, nil
212	}
213	
214	// SubmitReviewResult is the outcome of one submission attempt. Created is
215	// false when an identical submission (same ID and same field values) was
216	// retried: in that case Revision is the original revision and no new one is
217	// appended, even when the object was rejudged or withdrawn later.
218	type SubmitReviewResult struct {
219		Created   bool           `json:"created"`
220		ChainID   string         `json:"chainId"`
221		BlockHash string         `json:"blockHash"`
222		TxHash    string         `json:"txHash"`
223		Kind      string         `json:"kind"`
224		Status    string         `json:"status"`
225		Version   int            `json:"version"`
226		Revision  ReviewRevision `json:"revision"`
227	}
228	
229	// SubmitReview validates and stores one review revision. The target
230	// conclusion must exist in the archive. The first submission for an object
231	// must carry expectedVersion 0; every later one must carry the object's
232	// current version, otherwise the submission is rejected without touching
233	// stored data. Rejudgments and withdrawals append; older revisions stay.
234	// Identical retries (same archive-unique submission ID and identical
235	// fields) return the original revision. The whole update is one atomic
236	// commit under the archive lock, so concurrent submissions serialize and a
237	// stale concurrent submission can never overwrite another operator's
238	// revision.
239	func SubmitReview(dir string, sub ReviewSubmission) (SubmitReviewResult, error) {
240		if err := validateReviewIdentity(sub); err != nil {
241			return SubmitReviewResult{}, err
242		}
243		if err := os.MkdirAll(dir, 0o755); err != nil {
244			return SubmitReviewResult{}, err
245		}
246		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
247		if err != nil {
248			return SubmitReviewResult{}, err
249		}
250		defer lock.Close()
251	
252		data, err := readArchive(dir)
253		if err != nil {
254			return SubmitReviewResult{}, err
255		}
256		if _, _, ok := findArchivedConclusion(data, sub.key()); !ok {
257			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s",
258				ErrUnknownConclusion, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind)
259		}
260	
261		// Submission IDs are unique archive-wide. An ID reuse with identical
262		// content is an idempotent retry of the original revision; it must
263		// succeed (and append nothing) even when the object has since moved on.
264		for i := range data.Reviews {
265			obj := &data.Reviews[i]
266			for _, rev := range obj.Revisions {
267				if rev.SubmissionID != sub.SubmissionID {
268					continue
269				}
270				existing := ReviewSubmission{
271					ChainID:         obj.ChainID,
272					BlockHash:       obj.BlockHash,
273					TxHash:          obj.TxHash,
274					Kind:            obj.Kind,
275					SubmissionID:    rev.SubmissionID,
276					Operator:        rev.Operator,
277					Reason:          rev.Reason,
278					Status:          rev.Status,
279					ExpectedVersion: rev.ExpectedVersion,
280				}
281				if !sub.contentEqual(existing) {
282					return SubmitReviewResult{}, fmt.Errorf("%w: %s", ErrSubmissionConflict, sub.SubmissionID)
283				}
284				return SubmitReviewResult{
285					Created:   false,
286					ChainID:   obj.ChainID,
287					BlockHash: obj.BlockHash,
288					TxHash:    obj.TxHash,
289					Kind:      obj.Kind,
290					Status:    currentReviewStatus(*obj),
291					Version:   len(obj.Revisions),
292					Revision:  rev,
293				}, nil
294			}
295		}
296	
297		idx := -1
298		for i := range data.Reviews {
299			if data.Reviews[i].key() == sub.key() {
300				idx = i
301				break
302			}
303		}
304		if idx >= 0 && data.Reviews[idx].Revisions == nil {
305			data.Reviews[idx].Revisions = []ReviewRevision{}
306		}
307		currentVersion := 0
308		if idx >= 0 {
309			currentVersion = len(data.Reviews[idx].Revisions)
310		}
311		if sub.ExpectedVersion != currentVersion {
312			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s is at version %d, submission expected %d",
313				ErrReviewConflict, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind, currentVersion, sub.ExpectedVersion)
314		}
315		rev := sub.revision(currentVersion + 1)
316		if idx < 0 {
317			data.Reviews = append(data.Reviews, ReviewObject{
318				ChainID:   sub.ChainID,
319				BlockHash: sub.BlockHash,
320				TxHash:    sub.TxHash,
321				Kind:      sub.Kind,
322				Revisions: []ReviewRevision{rev},
323			})
324		} else {
325			data.Reviews[idx].Revisions = append(data.Reviews[idx].Revisions, rev)
326		}
327		if err := writeArchiveAtomic(dir, data); err != nil {
328			return SubmitReviewResult{}, err
329		}
330		return SubmitReviewResult{
331			Created:   true,
332			ChainID:   sub.ChainID,
333			BlockHash: sub.BlockHash,
334			TxHash:    sub.TxHash,
335			Kind:      sub.Kind,
336			Status:    sub.Status,
337			Version:   currentVersion + 1,
338			Revision:  rev,
339		}, nil
340	}
341	
342	func validateReviewIdentity(sub ReviewSubmission) error {
343		if strings.TrimSpace(sub.ChainID) == "" {
344			return errors.New("chainId must be a non-empty string")
345		}
346		if strings.TrimSpace(sub.BlockHash) == "" {
347			return errors.New("blockHash must be a non-empty string")
348		}
349		if strings.TrimSpace(sub.TxHash) == "" {
350			return errors.New("txHash must be a non-empty string")
351		}
352		if sub.Kind != SuppressSandwich && sub.Kind != SuppressDisplacement {
353			return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, sub.Kind)
354		}
355		if strings.TrimSpace(sub.SubmissionID) == "" {
356			return errors.New("submissionId must be a non-empty string")
357		}
358		if strings.TrimSpace(sub.Operator) == "" {
359			return errors.New("operator must be a non-empty string")
360		}
361		if strings.TrimSpace(sub.Reason) == "" {
362			return errors.New("reason must be a non-empty string")
363		}
364		switch sub.Status {
365		case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
366		default:
367			return fmt.Errorf("invalid status %q", sub.Status)
368		}
369		if sub.ExpectedVersion < 0 {
370			return fmt.Errorf("expectedVersion must be non-negative, got %d", sub.ExpectedVersion)
371		}
372		return nil
373	}
374	
375	// ReviewOriginal pairs the archived conclusion with the detection version
376	// (full parameters) that produced it.
377	type ReviewOriginal struct {
378		BlockNumber int64         `json:"blockNumber"`
379		Finding     ReportFinding `json:"finding"`
380		Version     RuleVersion   `json:"version"`
381	}
382	
383	// ReviewHistory is the full revision view of one conclusion object.
384	type ReviewHistory struct {
385		ChainID   string           `json:"chainId"`
386		BlockHash string           `json:"blockHash"`
387		TxHash    string           `json:"txHash"`
388		Kind      string           `json:"kind"`
389		Status    string           `json:"status"`
390		Version   int              `json:"version"`
391		Original  *ReviewOriginal  `json:"original"`
392		Revisions []ReviewRevision `json:"revisions"`
393	}
394	
395	// currentReviewStatus returns the latest revision's status. A trailing
396	// "unreviewed" revision means an earlier judgment was withdrawn.
397	func currentReviewStatus(obj ReviewObject) string {
398		if len(obj.Revisions) == 0 {
399			return ReviewStatusUnreviewed
400		}
401		return obj.Revisions[len(obj.Revisions)-1].Status
402	}
403	
404	// ReviewHistoryQuery returns the current status and version of one
405	// conclusion object plus every revision in ascending version order. Each
406	// revision keeps its full submission content, and the response carries the
407	// original archived conclusion, the detection version parameters and the
408	// raw swap evidence. An identity without review data reports status
409	// unreviewed, version 0 and an empty list; when no archived conclusion
410	// matches the identity, original is null.
411	func ReviewHistoryQuery(dir, chainID, blockHash, txHash, kind string) (ReviewHistory, error) {
412		if strings.TrimSpace(chainID) == "" || strings.TrimSpace(blockHash) == "" ||
413			strings.TrimSpace(txHash) == "" {
414			return ReviewHistory{}, errors.New("chainId, blockHash and txHash must be non-empty strings")
415		}
416		if kind != SuppressSandwich && kind != SuppressDisplacement {
417			return ReviewHistory{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
418		}
419		out := ReviewHistory{
420			ChainID:   chainID,
421			BlockHash: blockHash,
422			TxHash:    txHash,
423			Kind:      kind,
424			Status:    ReviewStatusUnreviewed,
425			Version:   0,
426			Original:  nil,
427			Revisions: []ReviewRevision{},
428		}
429		key := conclusionKey{chainID, blockHash, txHash, kind}
430		if _, serr := os.Stat(dir); serr != nil {
431			if errors.Is(serr, os.ErrNotExist) {
432				return out, nil
433			}
434			return ReviewHistory{}, serr
435		}
436		lock, err := lockArchive(dir, syscall.LOCK_SH)
437		if err != nil {
438			return ReviewHistory{}, err
439		}
440		defer lock.Close()
441	
442		data, err := readArchive(dir)
443		if err != nil {
444			return ReviewHistory{}, err
445		}
446		if rec, f, ok := findArchivedConclusion(data, key); ok {
447			out.Original = &ReviewOriginal{
448				BlockNumber: rec.BlockNumber,
449				Finding:     f,
450				Version:     rec.ruleVersion(),
451			}
452		}
453		for i := range data.Reviews {
454			obj := data.Reviews[i]
455			if obj.key() != key {
456				continue
457			}
458			out.Version = len(obj.Revisions)
459			out.Status = currentReviewStatus(obj)
460			out.Revisions = append([]ReviewRevision(nil), obj.Revisions...)
461			break
462		}
463		if out.Revisions == nil {
464			out.Revisions = []ReviewRevision{}
465		}
466		return out, nil
467	}
468	
469	// findArchivedConclusion locates the record and the finding for an identity.
470	func findArchivedConclusion(data archiveData, key conclusionKey) (record, ReportFinding, bool) {
471		for _, rec := range data.Records {
472			if rec.ChainID != key.chainID || rec.BlockHash != key.blockHash {
473				continue
474			}
475			for _, f := range rec.Findings {
476				if f.TxHash == key.txHash && f.Kind == key.kind {
477					return rec, f, true
478				}
479			}
480		}
481		return record{}, ReportFinding{}, false
482	}
483	
484	// ReviewConclusion pairs a conclusion with the rule version whose
485	// parameters produced it. The finding itself carries the raw swap evidence.
486	type ReviewConclusion struct {
487		Finding ReportFinding `json:"finding"`
488		Version RuleVersion   `json:"version"`
489	}
490	
491	// ReviewDetail is one evaluated conclusion with its bucket, the revision
492	// that decided it (null when there is no valid review), the original and
493	// candidate conclusions (either side may be null), their rule parameters
494	// and their swap evidence.
495	type ReviewDetail struct {
496		ChainID         string            `json:"chainId"`
497		BlockHash       string            `json:"blockHash"`
498		BlockNumber     int64             `json:"blockNumber"`
499		TxHash          string            `json:"txHash"`
500		Kind            string            `json:"kind"`
501		Bucket          string            `json:"bucket"`
502		AppliedRevision *ReviewRevision   `json:"appliedRevision"`
503		Original        *ReviewConclusion `json:"original"`
504		Candidate       *ReviewConclusion `json:"candidate"`
505	}
506	
507	// ReviewEvaluation is the false-positive analysis over one inclusive height
508	// range, judged consistently against one archive snapshot and its latest
509	// review state.
510	type ReviewEvaluation struct {
511		ChainID     string         `json:"chainId"`
512		StartHeight uint64         `json:"startHeight"`
513		EndHeight   uint64         `json:"endHeight"`
514		Version     RuleVersion    `json:"version"`
515		Retained    int            `json:"retained"`
516		Missed      int            `json:"missed"`
517		StillHit    int            `json:"stillHit"`
518		Eliminated  int            `json:"eliminated"`
519		Pending     int            `json:"pending"`
520		Details     []ReviewDetail `json:"details"`
521	}
522	
523	// sortReviewDetails orders by height, block hash, tx hash and kind.
524	func sortReviewDetails(details []ReviewDetail) {
525		sort.Slice(details, func(i, j int) bool {
526			a, b := details[i], details[j]
527			if a.BlockNumber != b.BlockNumber {
528				return a.BlockNumber < b.BlockNumber
529			}
530			if a.BlockHash != b.BlockHash {
531				return a.BlockHash < b.BlockHash
532			}
533			if a.TxHash != b.TxHash {
534				return a.TxHash < b.TxHash
535			}
536			return a.Kind < b.Kind
537		})
538	}
539	
540	// EvaluateReviews re-judges every archived block on chainID in the inclusive
541	// range [startHeight, endHeight] under the given registered rule version and
542	// compares the candidate conclusions against archived originals, using only
543	// archived evidence and the latest review state. Only original conclusions
544	// marked real or false positive feed the four counts: real risks split into
545	// retained (same tx and same kind still hits; severity changes do not
546	// matter) and missed; false positives split into still hit and eliminated.
547	// A candidate hit on the same tx and kind without a valid (non-withdrawn)
548	// review counts as pending, as does the new kind when the candidate changes
549	// a tx's conclusion type; withdrawn objects behave as unreviewed. The call
550	// is read-only: reports, the enabled version, reviews and alert records are
551	// never modified. An empty range yields zero counts and an empty list.
552	func EvaluateReviews(dir, chainID string, startHeight, endHeight uint64, versionID string) (ReviewEvaluation, error) {
553		if strings.TrimSpace(chainID) == "" {
554			return ReviewEvaluation{}, errors.New("chainId must be a non-empty string")
555		}
556		if strings.TrimSpace(versionID) == "" {
557			return ReviewEvaluation{}, errors.New("version id must not be empty")
558		}
559		if startHeight > endHeight {
560			return ReviewEvaluation{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
561		}
562		result := ReviewEvaluation{
563			ChainID:     chainID,
564			StartHeight: startHeight,
565			EndHeight:   endHeight,
566			Details:     []ReviewDetail{},
567		}
568		if _, serr := os.Stat(dir); serr != nil {
569			if errors.Is(serr, os.ErrNotExist) {
570				// An absent archive has only the built-in version registered, so
571				// any other id is an unknown version even though the range would
572				// match no blocks.
573				if versionID != BuiltinVersionID {
574					return ReviewEvaluation{}, fmt.Errorf("%w: %s", ErrUnknownVersion, versionID)
575				}
576				result.Version = BuiltinVersion()
577				return result, nil
578			}
579			return ReviewEvaluation{}, serr
580		}
581		// One shared lock for the whole evaluation: the archive snapshot and the
582		// latest review state stay consistent across every block.
583		lock, err := lockArchive(dir, syscall.LOCK_SH)
584		if err != nil {
585			return ReviewEvaluation{}, err
586		}
587		defer lock.Close()
588	
589		data, err := readArchive(dir)
590		if err != nil {
591			return ReviewEvaluation{}, err
592		}
593		candidate, err := findVersion(data, versionID)
594		if err != nil {
595			return ReviewEvaluation{}, err
596		}
597		result.Version = candidate
598	
599		reviews := make(map[conclusionKey]*ReviewObject, len(data.Reviews))
600		for i := range data.Reviews {
601			reviews[data.Reviews[i].key()] = &data.Reviews[i]
602		}
603	
604		details := []ReviewDetail{}
605		for _, rec := range data.Records {
606			if rec.ChainID != chainID {
607				continue
608			}
609			height := uint64(rec.BlockNumber)
610			if height < startHeight || height > endHeight {
611				continue
612			}
613			originalVersion := rec.ruleVersion()
614			candidateFindings := DetectBlockWithRules(rec.Swaps, candidate.Rules)
615			candByKey := make(map[conclusionKey]ReportFinding, len(candidateFindings))
616			candByTx := make(map[string]ReportFinding, len(candidateFindings))
617			for _, cf := range candidateFindings {
618				candByKey[conclusionKey{rec.ChainID, rec.BlockHash, cf.TxHash, cf.Kind}] = cf
619				candByTx[cf.TxHash] = cf
620			}
621	
622			// Original conclusions: only reviewed (real/false-positive) ones
623			// enter the four counts; same-kind candidate hits without a valid
624			// review are pending; originals that simply vanished without review
625			// are not counted anywhere.
626			for _, of := range rec.Findings {
627				key := conclusionKey{rec.ChainID, rec.BlockHash, of.TxHash, of.Kind}
628				obj := reviews[key]
629				original := &ReviewConclusion{Finding: of, Version: originalVersion}
630				if obj == nil || currentReviewStatus(*obj) == ReviewStatusUnreviewed {
631					if cf, ok := candByKey[key]; ok {
632						details = append(details, ReviewDetail{
633							ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
634							TxHash: of.TxHash, Kind: of.Kind, Bucket: BucketPending,
635							Original: original, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
636						})
637					}
638					continue
639				}
640				rev := obj.Revisions[len(obj.Revisions)-1]
641				detail := ReviewDetail{
642					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
643					TxHash: of.TxHash, Kind: of.Kind, AppliedRevision: &rev, Original: original,
644				}
645				cf, hit := candByKey[key]
646				if hit {
647					detail.Candidate = &ReviewConclusion{Finding: cf, Version: candidate}
648				}
649				switch rev.Status {
650				case ReviewStatusReal:
651					if hit {
652						detail.Bucket = BucketRetained
653					} else {
654						detail.Bucket = BucketMissed
655					}
656				case ReviewStatusFalsePositive:
657					if hit {
658						detail.Bucket = BucketStillHit
659					} else {
660						detail.Bucket = BucketEliminated
661					}
662				}
663				details = append(details, detail)
664			}
665	
666			// Candidate conclusions whose (tx, kind) matches no original: when
667			// the same tx carried a different original kind this is the "new
668			// type" side of a type change; either way it is unreviewed and
669			// pending.
670			for _, cf := range candidateFindings {
671				if _, sameKind := findOriginalFinding(rec, cf.TxHash, cf.Kind); sameKind {
672					continue
673				}
674				details = append(details, ReviewDetail{
675					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
676					TxHash: cf.TxHash, Kind: cf.Kind, Bucket: BucketPending,
677					Original: nil, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
678				})
679			}
680		}
681	
682		for _, d := range details {
683			switch d.Bucket {
684			case BucketRetained:
685				result.Retained++
686			case BucketMissed:
687				result.Missed++
688			case BucketStillHit:
689				result.StillHit++
690			case BucketEliminated:
691				result.Eliminated++
692			case BucketPending:
693				result.Pending++
694			}
695		}
696		sortReviewDetails(details)
697		result.Details = details
698		return result, nil
699	}
700	
701	func findOriginalFinding(rec record, txHash, kind string) (ReportFinding, bool) {
702		for _, f := range rec.Findings {
703			if f.TxHash == txHash && f.Kind == kind {
704				return f, true
705			}
706		}
707		return ReportFinding{}, false
708	}
709

