package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"
	"syscall"
)

// Manual review and false-positive analysis work strictly on top of
// archived evidence: submitting a review, querying revision history and
// re-evaluating a height range never need the original input files, never
// contact any network, never re-write a report, the enabled version or an
// alert record, and never trigger or revoke alerts.

// Review statuses. A human marks an archived conclusion either as a real
// risk or as a false positive; submitting "unreviewed" withdraws earlier
// judgments of the same object without deleting the history.
const (
	ReviewStatusReal          = "real"
	ReviewStatusFalsePositive = "false_positive"
	ReviewStatusUnreviewed    = "unreviewed"
)

// Evaluation buckets for original conclusions carrying a valid review:
// real risks split into retained vs missed, false positives into still hit
// vs eliminated. Candidate hits without a valid review are pending.
const (
	BucketRetained   = "retained"
	BucketMissed     = "missed"
	BucketStillHit   = "stillHit"
	BucketEliminated = "eliminated"
	BucketPending    = "pending"
)

// ErrUnknownConclusion reports a review action targeting a conclusion that
// no archived report carries.
var ErrUnknownConclusion = errors.New("unknown conclusion")

// ErrReviewConflict reports a submission whose expectedVersion is behind the
// object's current version.
var ErrReviewConflict = errors.New("review version conflict")

// ErrSubmissionConflict reports a submission ID already stored with
// different field values. Submission IDs are unique archive-wide.
var ErrSubmissionConflict = errors.New("submission id already used with different content")

// conclusionKey is the reviewed object's identity: chain, block hash,
// victim tx hash and conclusion kind. It deliberately excludes the alert
// channel, and blocks at the same height with different hashes are
// different objects.
type conclusionKey struct {
	chainID   string
	blockHash string
	txHash    string
	kind      string
}

// ReviewRevision is one immutable submission. Revisions are append-only:
// rejudgments and withdrawals add a new revision while every earlier one is
// retained. ExpectedVersion records the optimistic-concurrency base the
// submitter believed in (0 for the first submission), keeping each
// revision's full submission content auditable.
type ReviewRevision struct {
	Version         int    `json:"version"`
	SubmissionID    string `json:"submissionId"`
	Operator        string `json:"operator"`
	Reason          string `json:"reason"`
	Status          string `json:"status"`
	ExpectedVersion int    `json:"expectedVersion"`
}

// ReviewObject is the append-only revision stream for one conclusion
// identity. The current version is len(Revisions); the current status is
// the last revision's status (an "unreviewed" tail means withdrawn).
type ReviewObject struct {
	ChainID   string           `json:"chainId"`
	BlockHash string           `json:"blockHash"`
	TxHash    string           `json:"txHash"`
	Kind      string           `json:"kind"`
	Revisions []ReviewRevision `json:"revisions"`
}

func (o ReviewObject) key() conclusionKey {
	return conclusionKey{o.ChainID, o.BlockHash, o.TxHash, o.Kind}
}

// ReviewSubmission is one submitted review.
type ReviewSubmission struct {
	ChainID         string
	BlockHash       string
	TxHash          string
	Kind            string
	SubmissionID    string
	Operator        string
	Reason          string
	Status          string
	ExpectedVersion int
}

func (s ReviewSubmission) key() conclusionKey {
	return conclusionKey{s.ChainID, s.BlockHash, s.TxHash, s.Kind}
}

// contentEqual reports whether two submissions carry identical field
// values, including the target identity and the expected version.
func (s ReviewSubmission) contentEqual(o ReviewSubmission) bool {
	return s == o
}

func (s ReviewSubmission) revision(version int) ReviewRevision {
	return ReviewRevision{
		Version:         version,
		SubmissionID:    s.SubmissionID,
		Operator:        s.Operator,
		Reason:          s.Reason,
		Status:          s.Status,
		ExpectedVersion: s.ExpectedVersion,
	}
}

// reviewSpec mirrors one submission document. Pointers distinguish missing
// fields from explicit zero values; the decoder rejects unknown fields.
type reviewSpec struct {
	ChainID         *string `json:"chainId"`
	BlockHash       *string `json:"blockHash"`
	TxHash          *string `json:"txHash"`
	Kind            *string `json:"kind"`
	SubmissionID    *string `json:"submissionId"`
	Operator        *string `json:"operator"`
	Reason          *string `json:"reason"`
	Status          *string `json:"status"`
	ExpectedVersion *int    `json:"expectedVersion"`
}

// ParseReviewSubmission validates one submission document. Identity fields
// and operator/reason/submissionId must be non-empty, the status must be
// one of real, false_positive or unreviewed, expectedVersion must be a
// non-negative integer, and the kind must be a known conclusion kind.
func ParseReviewSubmission(raw []byte) (ReviewSubmission, error) {
	var spec reviewSpec
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&spec); err != nil {
		return ReviewSubmission{}, fmt.Errorf("invalid review spec: %w", err)
	}
	if dec.More() {
		return ReviewSubmission{}, errors.New("invalid review spec: unexpected trailing data")
	}
	chainID, err := nonEmpty("chainId", spec.ChainID)
	if err != nil {
		return ReviewSubmission{}, err
	}
	blockHash, err := nonEmpty("blockHash", spec.BlockHash)
	if err != nil {
		return ReviewSubmission{}, err
	}
	txHash, err := nonEmpty("txHash", spec.TxHash)
	if err != nil {
		return ReviewSubmission{}, err
	}
	kind, err := nonEmpty("kind", spec.Kind)
	if err != nil {
		return ReviewSubmission{}, err
	}
	if kind != SuppressSandwich && kind != SuppressDisplacement {
		return ReviewSubmission{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
	}
	submissionID, err := nonEmpty("submissionId", spec.SubmissionID)
	if err != nil {
		return ReviewSubmission{}, err
	}
	operator, err := nonEmpty("operator", spec.Operator)
	if err != nil {
		return ReviewSubmission{}, err
	}
	reason, err := nonEmpty("reason", spec.Reason)
	if err != nil {
		return ReviewSubmission{}, err
	}
	status, err := nonEmpty("status", spec.Status)
	if err != nil {
		return ReviewSubmission{}, err
	}
	switch status {
	case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
	default:
		return ReviewSubmission{}, fmt.Errorf("invalid status %q (want %s, %s or %s)",
			status, ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed)
	}
	if spec.ExpectedVersion == nil {
		return ReviewSubmission{}, errors.New("expectedVersion is required (non-negative integer)")
	}
	if *spec.ExpectedVersion < 0 {
		return ReviewSubmission{}, fmt.Errorf("expectedVersion must be non-negative, got %d", *spec.ExpectedVersion)
	}
	return ReviewSubmission{
		ChainID:         chainID,
		BlockHash:       blockHash,
		TxHash:          txHash,
		Kind:            kind,
		SubmissionID:    submissionID,
		Operator:        operator,
		Reason:          reason,
		Status:          status,
		ExpectedVersion: *spec.ExpectedVersion,
	}, nil
}

// SubmitReviewResult is the outcome of one submission attempt. Created is
// false when an identical submission (same ID and same field values) was
// retried: in that case Revision is the original revision and no new one is
// appended, even when the object was rejudged or withdrawn later.
type SubmitReviewResult struct {
	Created   bool           `json:"created"`
	ChainID   string         `json:"chainId"`
	BlockHash string         `json:"blockHash"`
	TxHash    string         `json:"txHash"`
	Kind      string         `json:"kind"`
	Status    string         `json:"status"`
	Version   int            `json:"version"`
	Revision  ReviewRevision `json:"revision"`
}

// SubmitReview validates and stores one review revision. The target
// conclusion must exist in the archive. The first submission for an object
// must carry expectedVersion 0; every later one must carry the object's
// current version, otherwise the submission is rejected without touching
// stored data. Rejudgments and withdrawals append; older revisions stay.
// Identical retries (same archive-unique submission ID and identical
// fields) return the original revision. The whole update is one atomic
// commit under the archive lock, so concurrent submissions serialize and a
// stale concurrent submission can never overwrite another operator's
// revision.
func SubmitReview(dir string, sub ReviewSubmission) (SubmitReviewResult, error) {
	if err := validateReviewIdentity(sub); err != nil {
		return SubmitReviewResult{}, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return SubmitReviewResult{}, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return SubmitReviewResult{}, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return SubmitReviewResult{}, err
	}
	if _, _, ok := findArchivedConclusion(data, sub.key()); !ok {
		return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s",
			ErrUnknownConclusion, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind)
	}

	// Submission IDs are unique archive-wide. An ID reuse with identical
	// content is an idempotent retry of the original revision; it must
	// succeed (and append nothing) even when the object has since moved on.
	for i := range data.Reviews {
		obj := &data.Reviews[i]
		for _, rev := range obj.Revisions {
			if rev.SubmissionID != sub.SubmissionID {
				continue
			}
			existing := ReviewSubmission{
				ChainID:         obj.ChainID,
				BlockHash:       obj.BlockHash,
				TxHash:          obj.TxHash,
				Kind:            obj.Kind,
				SubmissionID:    rev.SubmissionID,
				Operator:        rev.Operator,
				Reason:          rev.Reason,
				Status:          rev.Status,
				ExpectedVersion: rev.ExpectedVersion,
			}
			if !sub.contentEqual(existing) {
				return SubmitReviewResult{}, fmt.Errorf("%w: %s", ErrSubmissionConflict, sub.SubmissionID)
			}
			return SubmitReviewResult{
				Created:   false,
				ChainID:   obj.ChainID,
				BlockHash: obj.BlockHash,
				TxHash:    obj.TxHash,
				Kind:      obj.Kind,
				Status:    currentReviewStatus(*obj),
				Version:   len(obj.Revisions),
				Revision:  rev,
			}, nil
		}
	}

	idx := -1
	for i := range data.Reviews {
		if data.Reviews[i].key() == sub.key() {
			idx = i
			break
		}
	}
	if idx >= 0 && data.Reviews[idx].Revisions == nil {
		data.Reviews[idx].Revisions = []ReviewRevision{}
	}
	currentVersion := 0
	if idx >= 0 {
		currentVersion = len(data.Reviews[idx].Revisions)
	}
	if sub.ExpectedVersion != currentVersion {
		return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s is at version %d, submission expected %d",
			ErrReviewConflict, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind, currentVersion, sub.ExpectedVersion)
	}
	rev := sub.revision(currentVersion + 1)
	if idx < 0 {
		data.Reviews = append(data.Reviews, ReviewObject{
			ChainID:   sub.ChainID,
			BlockHash: sub.BlockHash,
			TxHash:    sub.TxHash,
			Kind:      sub.Kind,
			Revisions: []ReviewRevision{rev},
		})
	} else {
		data.Reviews[idx].Revisions = append(data.Reviews[idx].Revisions, rev)
	}
	if err := writeArchiveAtomic(dir, data); err != nil {
		return SubmitReviewResult{}, err
	}
	return SubmitReviewResult{
		Created:   true,
		ChainID:   sub.ChainID,
		BlockHash: sub.BlockHash,
		TxHash:    sub.TxHash,
		Kind:      sub.Kind,
		Status:    sub.Status,
		Version:   currentVersion + 1,
		Revision:  rev,
	}, nil
}

func validateReviewIdentity(sub ReviewSubmission) error {
	if strings.TrimSpace(sub.ChainID) == "" {
		return errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(sub.BlockHash) == "" {
		return errors.New("blockHash must be a non-empty string")
	}
	if strings.TrimSpace(sub.TxHash) == "" {
		return errors.New("txHash must be a non-empty string")
	}
	if sub.Kind != SuppressSandwich && sub.Kind != SuppressDisplacement {
		return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, sub.Kind)
	}
	if strings.TrimSpace(sub.SubmissionID) == "" {
		return errors.New("submissionId must be a non-empty string")
	}
	if strings.TrimSpace(sub.Operator) == "" {
		return errors.New("operator must be a non-empty string")
	}
	if strings.TrimSpace(sub.Reason) == "" {
		return errors.New("reason must be a non-empty string")
	}
	switch sub.Status {
	case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
	default:
		return fmt.Errorf("invalid status %q", sub.Status)
	}
	if sub.ExpectedVersion < 0 {
		return fmt.Errorf("expectedVersion must be non-negative, got %d", sub.ExpectedVersion)
	}
	return nil
}

// ReviewOriginal pairs the archived conclusion with the detection version
// (full parameters) that produced it.
type ReviewOriginal struct {
	BlockNumber int64         `json:"blockNumber"`
	Finding     ReportFinding `json:"finding"`
	Version     RuleVersion   `json:"version"`
}

// ReviewHistory is the full revision view of one conclusion object.
type ReviewHistory struct {
	ChainID   string           `json:"chainId"`
	BlockHash string           `json:"blockHash"`
	TxHash    string           `json:"txHash"`
	Kind      string           `json:"kind"`
	Status    string           `json:"status"`
	Version   int              `json:"version"`
	Original  *ReviewOriginal  `json:"original"`
	Revisions []ReviewRevision `json:"revisions"`
}

// currentReviewStatus returns the latest revision's status. A trailing
// "unreviewed" revision means an earlier judgment was withdrawn.
func currentReviewStatus(obj ReviewObject) string {
	if len(obj.Revisions) == 0 {
		return ReviewStatusUnreviewed
	}
	return obj.Revisions[len(obj.Revisions)-1].Status
}

// ReviewHistoryQuery returns the current status and version of one
// conclusion object plus every revision in ascending version order. Each
// revision keeps its full submission content, and the response carries the
// original archived conclusion, the detection version parameters and the
// raw swap evidence. An identity without review data reports status
// unreviewed, version 0 and an empty list; when no archived conclusion
// matches the identity, original is null.
func ReviewHistoryQuery(dir, chainID, blockHash, txHash, kind string) (ReviewHistory, error) {
	if strings.TrimSpace(chainID) == "" || strings.TrimSpace(blockHash) == "" ||
		strings.TrimSpace(txHash) == "" {
		return ReviewHistory{}, errors.New("chainId, blockHash and txHash must be non-empty strings")
	}
	if kind != SuppressSandwich && kind != SuppressDisplacement {
		return ReviewHistory{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
	}
	out := ReviewHistory{
		ChainID:   chainID,
		BlockHash: blockHash,
		TxHash:    txHash,
		Kind:      kind,
		Status:    ReviewStatusUnreviewed,
		Version:   0,
		Original:  nil,
		Revisions: []ReviewRevision{},
	}
	key := conclusionKey{chainID, blockHash, txHash, kind}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return out, nil
		}
		return ReviewHistory{}, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return ReviewHistory{}, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return ReviewHistory{}, err
	}
	if rec, f, ok := findArchivedConclusion(data, key); ok {
		out.Original = &ReviewOriginal{
			BlockNumber: rec.BlockNumber,
			Finding:     f,
			Version:     rec.ruleVersion(),
		}
	}
	for i := range data.Reviews {
		obj := data.Reviews[i]
		if obj.key() != key {
			continue
		}
		out.Version = len(obj.Revisions)
		out.Status = currentReviewStatus(obj)
		out.Revisions = append([]ReviewRevision(nil), obj.Revisions...)
		break
	}
	if out.Revisions == nil {
		out.Revisions = []ReviewRevision{}
	}
	return out, nil
}

// findArchivedConclusion locates the record and the finding for an identity.
func findArchivedConclusion(data archiveData, key conclusionKey) (record, ReportFinding, bool) {
	for _, rec := range data.Records {
		if rec.ChainID != key.chainID || rec.BlockHash != key.blockHash {
			continue
		}
		for _, f := range rec.Findings {
			if f.TxHash == key.txHash && f.Kind == key.kind {
				return rec, f, true
			}
		}
	}
	return record{}, ReportFinding{}, false
}

// ReviewConclusion pairs a conclusion with the rule version whose
// parameters produced it. The finding itself carries the raw swap evidence.
type ReviewConclusion struct {
	Finding ReportFinding `json:"finding"`
	Version RuleVersion   `json:"version"`
}

// ReviewDetail is one evaluated conclusion with its bucket, the revision
// that decided it (null when there is no valid review), the original and
// candidate conclusions (either side may be null), their rule parameters
// and their swap evidence.
type ReviewDetail struct {
	ChainID         string            `json:"chainId"`
	BlockHash       string            `json:"blockHash"`
	BlockNumber     int64             `json:"blockNumber"`
	TxHash          string            `json:"txHash"`
	Kind            string            `json:"kind"`
	Bucket          string            `json:"bucket"`
	AppliedRevision *ReviewRevision   `json:"appliedRevision"`
	Original        *ReviewConclusion `json:"original"`
	Candidate       *ReviewConclusion `json:"candidate"`
}

// ReviewEvaluation is the false-positive analysis over one inclusive height
// range, judged consistently against one archive snapshot and its latest
// review state.
type ReviewEvaluation struct {
	ChainID     string         `json:"chainId"`
	StartHeight uint64         `json:"startHeight"`
	EndHeight   uint64         `json:"endHeight"`
	Version     RuleVersion    `json:"version"`
	Retained    int            `json:"retained"`
	Missed      int            `json:"missed"`
	StillHit    int            `json:"stillHit"`
	Eliminated  int            `json:"eliminated"`
	Pending     int            `json:"pending"`
	Details     []ReviewDetail `json:"details"`
}

// sortReviewDetails orders by height, block hash, tx hash and kind.
func sortReviewDetails(details []ReviewDetail) {
	sort.Slice(details, func(i, j int) bool {
		a, b := details[i], details[j]
		if a.BlockNumber != b.BlockNumber {
			return a.BlockNumber < b.BlockNumber
		}
		if a.BlockHash != b.BlockHash {
			return a.BlockHash < b.BlockHash
		}
		if a.TxHash != b.TxHash {
			return a.TxHash < b.TxHash
		}
		return a.Kind < b.Kind
	})
}

// EvaluateReviews re-judges every archived block on chainID in the inclusive
// range [startHeight, endHeight] under the given registered rule version and
// compares the candidate conclusions against archived originals, using only
// archived evidence and the latest review state. Only original conclusions
// marked real or false positive feed the four counts: real risks split into
// retained (same tx and same kind still hits; severity changes do not
// matter) and missed; false positives split into still hit and eliminated.
// A candidate hit on the same tx and kind without a valid (non-withdrawn)
// review counts as pending, as does the new kind when the candidate changes
// a tx's conclusion type; withdrawn objects behave as unreviewed. The call
// is read-only: reports, the enabled version, reviews and alert records are
// never modified. An empty range yields zero counts and an empty list.
func EvaluateReviews(dir, chainID string, startHeight, endHeight uint64, versionID string) (ReviewEvaluation, error) {
	if strings.TrimSpace(chainID) == "" {
		return ReviewEvaluation{}, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(versionID) == "" {
		return ReviewEvaluation{}, errors.New("version id must not be empty")
	}
	if startHeight > endHeight {
		return ReviewEvaluation{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	result := ReviewEvaluation{
		ChainID:     chainID,
		StartHeight: startHeight,
		EndHeight:   endHeight,
		Details:     []ReviewDetail{},
	}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			// An absent archive has only the built-in version registered, so
			// any other id is an unknown version even though the range would
			// match no blocks.
			if versionID != BuiltinVersionID {
				return ReviewEvaluation{}, fmt.Errorf("%w: %s", ErrUnknownVersion, versionID)
			}
			result.Version = BuiltinVersion()
			return result, nil
		}
		return ReviewEvaluation{}, serr
	}
	// One shared lock for the whole evaluation: the archive snapshot and the
	// latest review state stay consistent across every block.
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	candidate, err := findVersion(data, versionID)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	result.Version = candidate

	reviews := make(map[conclusionKey]*ReviewObject, len(data.Reviews))
	for i := range data.Reviews {
		reviews[data.Reviews[i].key()] = &data.Reviews[i]
	}

	details := []ReviewDetail{}
	for _, rec := range data.Records {
		if rec.ChainID != chainID {
			continue
		}
		height := uint64(rec.BlockNumber)
		if height < startHeight || height > endHeight {
			continue
		}
		originalVersion := rec.ruleVersion()
		candidateFindings := DetectBlockWithRules(rec.Swaps, candidate.Rules)
		candByKey := make(map[conclusionKey]ReportFinding, len(candidateFindings))
		candByTx := make(map[string]ReportFinding, len(candidateFindings))
		for _, cf := range candidateFindings {
			candByKey[conclusionKey{rec.ChainID, rec.BlockHash, cf.TxHash, cf.Kind}] = cf
			candByTx[cf.TxHash] = cf
		}

		// Original conclusions: only reviewed (real/false-positive) ones
		// enter the four counts; same-kind candidate hits without a valid
		// review are pending; originals that simply vanished without review
		// are not counted anywhere.
		for _, of := range rec.Findings {
			key := conclusionKey{rec.ChainID, rec.BlockHash, of.TxHash, of.Kind}
			obj := reviews[key]
			original := &ReviewConclusion{Finding: of, Version: originalVersion}
			if obj == nil || currentReviewStatus(*obj) == ReviewStatusUnreviewed {
				if cf, ok := candByKey[key]; ok {
					details = append(details, ReviewDetail{
						ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
						TxHash: of.TxHash, Kind: of.Kind, Bucket: BucketPending,
						Original: original, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
					})
				}
				continue
			}
			rev := obj.Revisions[len(obj.Revisions)-1]
			detail := ReviewDetail{
				ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
				TxHash: of.TxHash, Kind: of.Kind, AppliedRevision: &rev, Original: original,
			}
			cf, hit := candByKey[key]
			if hit {
				detail.Candidate = &ReviewConclusion{Finding: cf, Version: candidate}
			}
			switch rev.Status {
			case ReviewStatusReal:
				if hit {
					detail.Bucket = BucketRetained
				} else {
					detail.Bucket = BucketMissed
				}
			case ReviewStatusFalsePositive:
				if hit {
					detail.Bucket = BucketStillHit
				} else {
					detail.Bucket = BucketEliminated
				}
			}
			details = append(details, detail)
		}

		// Candidate conclusions whose (tx, kind) matches no original: when
		// the same tx carried a different original kind this is the "new
		// type" side of a type change; either way it is unreviewed and
		// pending.
		for _, cf := range candidateFindings {
			if _, sameKind := findOriginalFinding(rec, cf.TxHash, cf.Kind); sameKind {
				continue
			}
			details = append(details, ReviewDetail{
				ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
				TxHash: cf.TxHash, Kind: cf.Kind, Bucket: BucketPending,
				Original: nil, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
			})
		}
	}

	for _, d := range details {
		switch d.Bucket {
		case BucketRetained:
			result.Retained++
		case BucketMissed:
			result.Missed++
		case BucketStillHit:
			result.StillHit++
		case BucketEliminated:
			result.Eliminated++
		case BucketPending:
			result.Pending++
		}
	}
	sortReviewDetails(details)
	result.Details = details
	return result, nil
}

func findOriginalFinding(rec record, txHash, kind string) (ReportFinding, bool) {
	for _, f := range rec.Findings {
		if f.TxHash == txHash && f.Kind == kind {
			return f, true
		}
	}
	return ReportFinding{}, false
}

content.content:
1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"sort"
10		"strconv"
11		"strings"
12		"syscall"
13	)
14	
15	// Offline alerting turns conclusions already stored in an archive into
16	// alert processing records. It never re-runs detection: a record always
17	// reflects the finding, the rule version and the parameters that were in
18	// force when the block was archived.
19	
20	// Alert statuses. A finding above the generation threshold becomes an
21	// "alert"; a finding that matches one or more registered suppression
22	// conditions at its block height becomes "suppressed" instead.
23	const (
24		AlertStatusAlert      = "alert"
25		AlertStatusSuppressed = "suppressed"
26	)
27	
28	// Suppression condition kinds.
29	const (
30		SuppressSandwich     = "sandwich"
31		SuppressDisplacement = "displacement"
32	)
33	
34	// ErrUnknownKind reports a conclusion/condition kind that is neither
35	// sandwich nor displacement.
36	var ErrUnknownKind = errors.New("unknown kind")
37	
38	// ErrSuppressionConflict reports re-registering an existing suppression ID
39	// with different content.
40	var ErrSuppressionConflict = errors.New("suppression already registered with different content")
41	
42	// ErrUnknownSuppression reports revoking a condition ID that is not
43	// registered in the archive (including the empty archive).
44	var ErrUnknownSuppression = errors.New("unknown suppression condition")
45	
46	// SuppressionHit records one suppression condition that matched an event.
47	type SuppressionHit struct {
48		ID     string `json:"id"`
49		Reason string `json:"reason"`
50	}
51	
52	// ProcessingRecord is one fully resolved alerting outcome. Its identity is
53	// (chain, block hash, victim tx hash, conclusion kind, channel): once a
54	// record exists for that identity, no later import, wider or overlapping
55	// height range, rule-version switch or restart can produce it again. The
56	// record keeps the complete block identity, pool, conclusion, raw swap
57	// evidence, the detection version and its parameters, the threshold used at
58	// generation time, and every suppression condition that matched.
59	type ProcessingRecord struct {
60		ChainID      string           `json:"chainId"`
61		BlockHash    string           `json:"blockHash"`
62		BlockNumber  uint64           `json:"blockNumber"`
63		Pool         string           `json:"pool"`
64		Channel      string           `json:"channel"`
65		Finding      ReportFinding    `json:"finding"`
66		Version      RuleVersion      `json:"version"`
67		MinSeverity  int              `json:"minSeverity"`
68		Status       string           `json:"status"`
69		Suppressions []SuppressionHit `json:"suppressions"`
70	}
71	
72	func (r ProcessingRecord) identity() alertKey {
73		return alertKey{
74			chainID:   r.ChainID,
75			blockHash: r.BlockHash,
76			txHash:    r.Finding.TxHash,
77			kind:      r.Finding.Kind,
78			channel:   r.Channel,
79		}
80	}
81	
82	// Suppression is one registered suppression condition. Every field matches
83	// exactly (the pool is matched against the pool of the victim swap's
84	// original exchange record), and an event at height h is covered when
85	// StartHeight <= h <= EndHeight.
86	//
87	// Revoked marks a condition whose user has withdrawn it. A revoked
88	// condition is kept for audit but never matches later processing; the
89	// field is always serialized (an absent value in an old archive decodes
90	// to false, i.e. not revoked) and cannot be set through a registration
91	// document. Revocation applies to findings processed afterwards only —
92	// event height never decides when it takes effect.
93	type Suppression struct {
94		ID          string `json:"id"`
95		ChainID     string `json:"chainId"`
96		Pool        string `json:"pool"`
97		Kind        string `json:"kind"`
98		Channel     string `json:"channel"`
99		StartHeight uint64 `json:"startHeight"`
100		EndHeight   uint64 `json:"endHeight"`
101		Reason      string `json:"reason"`
102		Revoked     bool   `json:"revoked"`
103	}
104	
105	// covers reports whether the suppression applies to an event on chain at
106	// height in the given pool/kind/channel. Matching depends only on the
107	// event's height, never on operation time, import order or the archive's
108	// highest block.
109	func (s Suppression) covers(chainID, pool, kind, channel string, height uint64) bool {
110		return s.ChainID == chainID && s.Pool == pool && s.Kind == kind && s.Channel == channel &&
111			s.StartHeight <= height && height <= s.EndHeight
112	}
113	
114	// alertKey is the deduplication identity of a processing record.
115	type alertKey struct {
116		chainID   string
117		blockHash string
118		txHash    string
119		kind      string
120		channel   string
121	}
122	
123	// suppressionSpec mirrors one suppression registration document. Pointers
124	// distinguish missing fields from explicit zero values; heights are parsed
125	// separately as unsigned 64-bit integers.
126	type suppressionSpec struct {
127		ID          *string `json:"id"`
128		ChainID     *string `json:"chainId"`
129		Pool        *string `json:"pool"`
130		Kind        *string `json:"kind"`
131		Channel     *string `json:"channel"`
132		StartHeight *uint64 `json:"startHeight"`
133		EndHeight   *uint64 `json:"endHeight"`
134		Reason      *string `json:"reason"`
135	}
136	
137	func nonEmpty(field string, v *string) (string, error) {
138		if v == nil {
139			return "", fmt.Errorf("%s is required (non-empty string)", field)
140		}
141		if strings.TrimSpace(*v) == "" {
142			return "", fmt.Errorf("%s must be a non-empty string", field)
143		}
144		return *v, nil
145	}
146	
147	// ParseSuppression validates one registration document. Only sandwich and
148	// displacement kinds exist, every text field must be non-empty, heights are
149	// unsigned 64-bit integers and the start height must not exceed the end
150	// height.
151	func ParseSuppression(raw []byte) (Suppression, error) {
152		var spec suppressionSpec
153		dec := json.NewDecoder(bytes.NewReader(raw))
154		dec.DisallowUnknownFields()
155		if err := dec.Decode(&spec); err != nil {
156			return Suppression{}, fmt.Errorf("invalid suppression spec: %w", err)
157		}
158		if dec.More() {
159			return Suppression{}, errors.New("invalid suppression spec: unexpected trailing data")
160		}
161		id, err := nonEmpty("id", spec.ID)
162		if err != nil {
163			return Suppression{}, err
164		}
165		chainID, err := nonEmpty("chainId", spec.ChainID)
166		if err != nil {
167			return Suppression{}, err
168		}
169		pool, err := nonEmpty("pool", spec.Pool)
170		if err != nil {
171			return Suppression{}, err
172		}
173		kind, err := nonEmpty("kind", spec.Kind)
174		if err != nil {
175			return Suppression{}, err
176		}
177		if kind != SuppressSandwich && kind != SuppressDisplacement {
178			return Suppression{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
179		}
180		channel, err := nonEmpty("channel", spec.Channel)
181		if err != nil {
182			return Suppression{}, err
183		}
184		if spec.StartHeight == nil {
185			return Suppression{}, errors.New("startHeight is required (unsigned 64-bit integer)")
186		}
187		if spec.EndHeight == nil {
188			return Suppression{}, errors.New("endHeight is required (unsigned 64-bit integer)")
189		}
190		if *spec.StartHeight > *spec.EndHeight {
191			return Suppression{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", *spec.StartHeight, *spec.EndHeight)
192		}
193		reason, err := nonEmpty("reason", spec.Reason)
194		if err != nil {
195			return Suppression{}, err
196		}
197		return Suppression{
198			ID:          id,
199			ChainID:     chainID,
200			Pool:        pool,
201			Kind:        kind,
202			Channel:     channel,
203			StartHeight: *spec.StartHeight,
204			EndHeight:   *spec.EndHeight,
205			Reason:      reason,
206		}, nil
207	}
208	
209	// ParseHeight parses a non-negative 64-bit integer height. Signs, fractions,
210	// blanks and values above 2^64-1 are rejected.
211	func ParseHeight(text string) (uint64, error) {
212		if text == "" {
213			return 0, errors.New("height must be a non-empty unsigned 64-bit integer")
214		}
215		h, err := strconv.ParseUint(text, 10, 64)
216		if err != nil {
217			return 0, fmt.Errorf("invalid height %q: %w", text, err)
218		}
219		return h, nil
220	}
221	
222	// ValidateSeverity accepts the integer threshold range 1..5 inclusive; the
223	// threshold itself counts as a hit.
224	func ValidateSeverity(severity int) error {
225		if severity < 1 || severity > 5 {
226			return fmt.Errorf("minSeverity must be between 1 and 5, got %d", severity)
227		}
228		return nil
229	}
230	
231	// suppressionEqual reports whether two conditions carry identical
232	// registration content. Revoked state is intentionally excluded: retrying
233	// the same document is idempotent even after the condition was revoked
234	// (and never re-enables it), while differing content still conflicts.
235	func suppressionEqual(a, b Suppression) bool {
236		return a.ID == b.ID &&
237			a.ChainID == b.ChainID &&
238			a.Pool == b.Pool &&
239			a.Kind == b.Kind &&
240			a.Channel == b.Channel &&
241			a.StartHeight == b.StartHeight &&
242			a.EndHeight == b.EndHeight &&
243			a.Reason == b.Reason
244	}
245	
246	// matchSuppressions returns every active condition covering the event,
247	// sorted by ID in lexicographic order so overlapping conditions are
248	// reported deterministically. Revoked conditions are skipped: they no
249	// longer apply to conclusions processed after the revocation.
250	func matchSuppressions(conds []Suppression, chainID, pool, kind, channel string, height uint64) []SuppressionHit {
251		hits := []SuppressionHit{}
252		for _, s := range conds {
253			if s.Revoked {
254				continue
255			}
256			if s.covers(chainID, pool, kind, channel, height) {
257				hits = append(hits, SuppressionHit{ID: s.ID, Reason: s.Reason})
258			}
259		}
260		sort.Slice(hits, func(i, j int) bool { return hits[i].ID < hits[j].ID })
261		return hits
262	}
263	
264	// victimPool returns the pool of the victim swap inside the finding's raw
265	// evidence. The victim is the swap whose TxHash matches the finding; the
266	// evidence ordering and count vary by conclusion kind, so the pool is read
267	// off the original exchange record rather than inferred from position.
268	func victimPool(f ReportFinding) (string, bool) {
269		for _, s := range f.Evidence {
270			if s.TxHash == f.TxHash {
271				return s.Pool, true
272			}
273		}
274		return "", false
275	}
276	
277	// sortRecords orders processing records by height, block hash, tx hash and
278	// kind ascending. Channel stays out of the ordering key: generation runs for
279	// one channel, history may span several.
280	func sortRecords(records []ProcessingRecord) {
281		sort.Slice(records, func(i, j int) bool {
282			a, b := records[i], records[j]
283			if a.BlockNumber != b.BlockNumber {
284				return a.BlockNumber < b.BlockNumber
285			}
286			if a.BlockHash != b.BlockHash {
287				return a.BlockHash < b.BlockHash
288			}
289			if a.Finding.TxHash != b.Finding.TxHash {
290				return a.Finding.TxHash < b.Finding.TxHash
291			}
292			return a.Finding.Kind < b.Finding.Kind
293		})
294	}
295	
296	// GenerateAlerts turns archived conclusions in the inclusive range
297	// [startHeight, endHeight] on chainID for channel into new processing
298	// records. Detection is not re-run: the archived finding, evidence and rule
299	// version are reused. A finding at least minSeverity is processed; findings
300	// below the threshold leave no record, so lowering the threshold later can
301	// still produce them. Every already-processed identity is skipped, which
302	// makes repeated imports, repeated generation, wider or overlapping ranges,
303	// version switches and restarts idempotent. Channels are independent, and
304	// blocks at the same height with different hashes are handled separately.
305	//
306	// All new records of one call are committed together or not at all. The
307	// returned slice contains only records created by this call (alerts and
308	// suppressions distinguished), sorted by height, block hash, tx hash and
309	// kind; an empty result serializes as [].
310	func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
311		if strings.TrimSpace(chainID) == "" {
312			return nil, errors.New("chainId must be a non-empty string")
313		}
314		if strings.TrimSpace(channel) == "" {
315			return nil, errors.New("channel must be a non-empty name")
316		}
317		if err := ValidateSeverity(minSeverity); err != nil {
318			return nil, err
319		}
320		if startHeight > endHeight {
321			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
322		}
323		if err := os.MkdirAll(dir, 0o755); err != nil {
324			return nil, err
325		}
326		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
327		if err != nil {
328			return nil, err
329		}
330		defer lock.Close()
331	
332		data, err := readArchive(dir)
333		if err != nil {
334			return nil, err
335		}
336		processed := make(map[alertKey]struct{}, len(data.AlertRecords))
337		for _, r := range data.AlertRecords {
338			processed[r.identity()] = struct{}{}
339		}
340	
341		created := []ProcessingRecord{}
342		for _, rec := range data.Records {
343			if rec.ChainID != chainID {
344				continue
345			}
346			height := uint64(rec.BlockNumber)
347			if height < startHeight || height > endHeight {
348				continue
349			}
350			version := rec.ruleVersion()
351			for _, f := range rec.Findings {
352				if f.Severity < minSeverity {
353					// Below the threshold: no record is written, so the event
354					// stays eligible after a later threshold reduction.
355					continue
356				}
357				key := alertKey{
358					chainID:   rec.ChainID,
359					blockHash: rec.BlockHash,
360					txHash:    f.TxHash,
361					kind:      f.Kind,
362					channel:   channel,
363				}
364				if _, ok := processed[key]; ok {
365					continue
366				}
367				pool, ok := victimPool(f)
368				if !ok {
369					return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
370						rec.ChainID, rec.BlockHash, f.TxHash)
371				}
372				hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
373				status := AlertStatusAlert
374				if len(hits) > 0 {
375					status = AlertStatusSuppressed
376				}
377				record := ProcessingRecord{
378					ChainID:      rec.ChainID,
379					BlockHash:    rec.BlockHash,
380					BlockNumber:  height,
381					Pool:         pool,
382					Channel:      channel,
383					Finding:      f,
384					Version:      version,
385					MinSeverity:  minSeverity,
386					Status:       status,
387					Suppressions: hits,
388				}
389				created = append(created, record)
390				processed[key] = struct{}{}
391			}
392		}
393		sortRecords(created)
394		if len(created) > 0 {
395			data.AlertRecords = append(data.AlertRecords, created...)
396			if err := writeArchiveAtomic(dir, data); err != nil {
397				return nil, err
398			}
399		}
400		return created, nil
401	}
402	
403	// AlertHistory returns stored processing records on chainID for channel in
404	// the inclusive range [startHeight, endHeight]. It only reads the archive;
405	// suppressions registered afterwards cannot alter the stored content.
406	func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
407		if strings.TrimSpace(chainID) == "" {
408			return nil, errors.New("chainId must be a non-empty string")
409		}
410		if strings.TrimSpace(channel) == "" {
411			return nil, errors.New("channel must be a non-empty name")
412		}
413		if startHeight > endHeight {
414			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
415		}
416		if _, serr := os.Stat(dir); serr != nil {
417			if errors.Is(serr, os.ErrNotExist) {
418				return []ProcessingRecord{}, nil
419			}
420			return nil, serr
421		}
422		lock, err := lockArchive(dir, syscall.LOCK_SH)
423		if err != nil {
424			return nil, err
425		}
426		defer lock.Close()
427	
428		data, err := readArchive(dir)
429		if err != nil {
430			return nil, err
431		}
432		out := []ProcessingRecord{}
433		for _, r := range data.AlertRecords {
434			if r.ChainID != chainID || r.Channel != channel {
435				continue
436			}
437			if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
438				continue
439			}
440			out = append(out, r)
441		}
442		sortRecords(out)
443		return out, nil
444	}
445	
446	// RegisterSuppression validates raw and stores one suppression condition in
447	// the archive. Re-registering the same ID with identical content succeeds
448	// without adding anything (created is false) — this stays true after the
449	// condition was revoked and never re-enables it; the same ID with different
450	// content is rejected. New conditions only affect conclusions that have not
451	// been processed yet: historical alerts are never rewritten as suppressed,
452	// and suppressed records are not re-alerted when a condition's range ends.
453	// The registration document cannot set revoked state.
454	func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
455		s, err = ParseSuppression(raw)
456		if err != nil {
457			return Suppression{}, false, err
458		}
459		if err := os.MkdirAll(dir, 0o755); err != nil {
460			return Suppression{}, false, err
461		}
462		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
463		if lerr != nil {
464			return Suppression{}, false, lerr
465		}
466		defer lock.Close()
467	
468		data, err := readArchive(dir)
469		if err != nil {
470			return Suppression{}, false, err
471		}
472		for _, existing := range data.Suppressions {
473			if existing.ID == s.ID {
474				if suppressionEqual(existing, s) {
475					return existing, false, nil
476				}
477				return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
478			}
479		}
480		data.Suppressions = append(data.Suppressions, s)
481		if err := writeArchiveAtomic(dir, data); err != nil {
482			return Suppression{}, false, err
483		}
484		return s, true, nil
485	}
486	
487	// RevokeSuppression withdraws the condition with the given exact ID. The
488	// first successful revocation returns changed=true and the full condition
489	// with Revoked set; revoking the same ID again succeeds with changed=false.
490	// A blank ID is rejected, and an ID that was never registered — including
491	// any ID in an empty archive — returns ErrUnknownSuppression. The revoked
492	// condition is retained (still listed) but stops matching conclusions
493	// processed from now on; it cannot be revived, a fresh ID is required to
494	// suppress again.
495	//
496	// The revocation is committed atomically under the archive lock: a busy
497	// archive, a corrupted one or a failed save leaves every condition, report
498	// and processing record untouched. One generation run always sees either
499	// the pre- or the post-revocation condition set in full.
500	func RevokeSuppression(dir, id string) (s Suppression, changed bool, err error) {
501		if strings.TrimSpace(id) == "" {
502			return Suppression{}, false, errors.New("suppression id must be a non-empty string")
503		}
504		if err := os.MkdirAll(dir, 0o755); err != nil {
505			return Suppression{}, false, err
506		}
507		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
508		if lerr != nil {
509			return Suppression{}, false, lerr
510		}
511		defer lock.Close()
512	
513		data, err := readArchive(dir)
514		if err != nil {
515			return Suppression{}, false, err
516		}
517		for i := range data.Suppressions {
518			if data.Suppressions[i].ID != id {
519				continue
520			}
521			if data.Suppressions[i].Revoked {
522				return data.Suppressions[i], false, nil
523			}
524			data.Suppressions[i].Revoked = true
525			if err := writeArchiveAtomic(dir, data); err != nil {
526				return Suppression{}, false, err
527			}
528			return data.Suppressions[i], true, nil
529		}
530		return Suppression{}, false, fmt.Errorf("%w: %s", ErrUnknownSuppression, id)
531	}
532	
533	// ListSuppressions returns every suppression condition stored in the
534	// archive, ordered by ID. A read on an absent archive returns an empty list.
535	func ListSuppressions(dir string) ([]Suppression, error) {
536		if _, serr := os.Stat(dir); serr != nil {
537			if errors.Is(serr, os.ErrNotExist) {
538				return []Suppression{}, nil
539			}
540			return nil, serr
541		}
542		lock, err := lockArchive(dir, syscall.LOCK_SH)
543		if err != nil {
544			return nil, err
545		}
546		defer lock.Close()
547	
548		data, err := readArchive(dir)
549		if err != nil {
550			return nil, err
551		}
552		out := append([]Suppression(nil), data.Suppressions...)
553		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
554		if out == nil {
555			out = []Suppression{}
556		}
557		return out, nil
558	}
559

