   func checkDuplicateFields(raw []byte) error {
       dec := json.NewDecoder(bytes.NewReader(raw))
       tok, err := dec.Token()
       if err != nil { return err-ish } // includes empty input, incomplete
       d, ok := tok.(json.Delim)
       if !ok || d != '{' { return not-object error }
       seen := map[string]string{}
       for dec.More() {
           kt, err := dec.Token()
           if err != nil { return err }
           key := kt.(string)
           canonical := canonicalField(key) // EqualFold match against known names
           if canonical != "" {
               if prev, dup := seen[canonical]; dup {
                   return fmt.Errorf("duplicate field %q (already given as %q)", key, prev) // must name the field
               }
               seen[canonical] = key
           }
           var v json.RawMessage
           if err := dec.Decode(&v); err != nil { return err }
       }
       // closing delim
       if _, err := dec.Token(); err != nil { return err }
       // trailing check
       var extra json.RawMessage
       if err := dec.Decode(&extra); err != io.EOF {
           return trailing error
       }
       return nil
   }
